insert into public.reviews (id, author_name, author_photo_url, rating, content, review_date, source, is_published, sort_order) values
  ('00000000-0000-4000-8010-000000000001', 'Rina A.', null, 5, 'Kitchen set-nya rapi banget, sesuai desain 3D. Tim datang tepat waktu dan instalasi bersih.', '2026-09-12', 'manual', true, 1),
  ('00000000-0000-4000-8010-000000000002', 'Budi S.', null, 5, 'Harga transparan dari awal, tidak ada biaya tersembunyi. Wardrobe duco-nya mulus.', '2026-08-28', 'manual', true, 2),
  ('00000000-0000-4000-8010-000000000003', 'Dewi K.', null, 5, 'Konsultasi via WhatsApp responsif, dibantu pilih HPL yang cocok. Hasilnya memuaskan.', '2026-08-03', 'manual', true, 3),
  ('00000000-0000-4000-8010-000000000004', 'Andi P.', null, 4, 'Kualitas material bagus, pengerjaan sedikit mundur karena hujan tapi dikomunikasikan dengan baik.', '2026-07-19', 'manual', true, 4),
  ('00000000-0000-4000-8010-000000000005', 'Sari M.', null, 5, 'TV cabinet dan backdrop-nya jadi pusat perhatian ruang keluarga. Recommended!', '2026-06-30', 'manual', true, 5)
