insert into public.faqs (id, question, answer, sort_order, is_active) values
  ('00000000-0000-4000-8013-000000000001', 'Berapa lama pengerjaan kitchen set?', 'Rata-rata 3–5 minggu setelah desain disetujui dan DP diterima, tergantung ukuran dan finishing. Cat duco umumnya butuh waktu lebih lama dibanding HPL karena proses pengecatan berlapis.', 1, true),
  ('00000000-0000-4000-8013-000000000002', 'Apakah survey dan pengukuran dikenakan biaya?', 'Survey dan pengukuran gratis untuk area kota kami. Untuk luar kota, biaya transport dikonfirmasi lebih dulu sebelum jadwal survey.', 2, true),
  ('00000000-0000-4000-8013-000000000003', 'Apa beda finishing HPL dan cat duco?', 'HPL adalah lapisan laminasi yang tahan gores dan mudah dirawat dengan pilihan motif kayu, marmer, dan solid. Cat duco memberi tampilan mulus tanpa sambungan dengan warna bebas, cocok untuk desain modern dan klasik.', 3, true),
  ('00000000-0000-4000-8013-000000000004', 'Apakah harga di kalkulator sudah final?', 'Kalkulator memberi estimasi berdasarkan harga per meter terbaru. Harga final ditentukan setelah survey, karena ukuran detail, kondisi dinding, dan pilihan aksesoris bisa memengaruhi biaya.', 4, true),
  ('00000000-0000-4000-8013-000000000005', 'Bagaimana sistem pembayarannya?', 'Umumnya DP 50% saat desain disetujui, 40% sebelum pengiriman, dan 10% setelah instalasi selesai. Detailnya tertulis di surat penawaran.', 5, true),
  ('00000000-0000-4000-8013-000000000006', 'Apakah ada garansi?', 'Ya. Kami memberi garansi konstruksi dan hardware. Jika ada kendala setelah instalasi, cukup hubungi kami lewat WhatsApp.', 6, true)
